const lev=(a,b)=>{if(Math.abs(a.length-b.length)>2)return 9;let p=[...Array(b.length+1).keys()];for(let i=1;i<=a.length;i++){const c=[i];for(let j=1;j<=b.length;j++)c[j]=Math.min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]===b[j-1]?0:1));p=c}return p[b.length]};
const words=t=>String(t).toLowerCase().match(/[a-z0-9]+/g)||[];
const STOP=new Set('how much what where when who is are the a an to of for my in on do does can i change edit remove add set update find'.split(' '));
const qWords=t=>{const w=words(t),k=w.filter(x=>!STOP.has(x));return k.length?k:w};
const NEAR={views:['Hero','Gallery'],tests:['Show prices','Discount','Panels','Variants'],holds:['Bookings','Opening hours'],team:['Show photos','Role categories','Years of experience'],bookings:['Lab off times','Tests','WhatsApp'],theme:['Fonts','Ripple','Glass'],effects:['Ring size','Ripple radius','Glass blur','Colors'],services:['Show images','Tests','Doctors'],users:['Permissions','Audit log'],audit:['Users','Bookings'],blog:['Blog agent','SEO'],blog_agent:['AI key','Articles','SEO'],visit:['WhatsApp','Hours','Map link'],brand:['Logo','Colors'],hero:['Section order','Main button','Numbers'],layout:['Hero','Services'],trust:['Logos','Registration'],faq:['Services','Visit']};
const wScore=(q,w)=>w===q?100:w.startsWith(q)?82:w.includes(q)&&q.length>3?60:(()=>{if(q.length<5)return 0;const d=lev(q,w);return d===1?54:d===2&&q.length>6?38:0})();
const score=(qs,text)=>{const ws=words(text);let t=0;for(const q of qs){const b=Math.max(0,...ws.map(w=>wScore(q,w)));if(!b)return 0;t+=b}return t/qs.length};
const buildIndex=()=>{const r=[];const add=(page,title,hint,extra={})=>allowed(page)&&r.push({page,title,hint,...extra});
 Object.keys({...PAGES,...S}).forEach(k=>add(k,labelOf(k),groupOf(k)));
 Object.entries(S).forEach(([k,s])=>s.f.forEach(f=>add(k,f.l.replace(/\s*\(.*\)$/,''),s.label,{field:f.k})));
 const items=(k,listK,titleK,hint)=>(draft[k]?.[listK]||[]).forEach((it,i)=>it[titleK]&&add(k,it[titleK],hint,{open:listK+'.'+i,key:listK+'.'+i}));
 items('team','members','name','Person');items('team','roles','name','Role category');items('tests','items','name','Test');items('services','items','title','Service');items('faq','items','q','Question');return r};
const POPULAR=['Bookings','Lab off times','Show prices','Colors','Doctors','Ripple'];
