 if(repFrom){const b=repFrom;repFrom=null;ed(blank(b));return}const a=await FA.rpc('admin_reports');p.innerHTML=`<h2>Lab reports</h2><p class="psub">Newest first. Only approved reports reach patients.</p><div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap"><input id="rf" type="search" placeholder="Search patient, ID or report" style="flex:1;min-width:200px;min-height:42px;border:1px solid var(--bd);border-radius:10px;padding:0 12px;font:inherit"><button class="btn acc sm" id="na">New report</button></div><div class="pnl glass scroll"><table class="tb" id="rt2"></table></div>`;
