function login(err=''){document.documentElement.classList.remove('no-glass');$('#app').innerHTML=`<div class="login"><form class="glass" id="lf"><img src="/img/logo.webp" width="64" height="64" alt=""><h2 style="margin-top:10px">Admin sign in</h2>${FA.demo?'<div class="note">Preview mode. Any email and password will work. Changes stay in this browser.</div>':''}<div class="fld"><label>Email</label><input type="email" id="le" required></div><div class="fld"><label>Password</label><input type="password" id="lp" required></div><button class="btn acc" style="width:100%">Sign in</button><p class="err" id="er">${e(err)}</p></form></div>`;$('#lf').onsubmit=async ev=>{ev.preventDefault();try{await FA.login($('#le').value,$('#lp').value);start()}catch(x){$('#er').textContent=x.message}}}
